CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_birth_date`(p_min_age INT, p_max_age INT) RETURNS date
    NO SQL
BEGIN
    DECLARE v_oldest   DATE;   
    DECLARE v_youngest DATE;   
    SET v_oldest   = DATE_ADD(DATE_SUB(CURDATE(), INTERVAL (p_max_age + 1) YEAR), INTERVAL 1 DAY);
    SET v_youngest = DATE_SUB(CURDATE(), INTERVAL p_min_age YEAR);
    RETURN DATE_ADD(v_oldest, INTERVAL fn_gen_random_int(0, DATEDIFF(v_youngest, v_oldest)) DAY);
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_datetime_between`(p_from DATETIME, p_to DATETIME) RETURNS datetime
    NO SQL
BEGIN
    RETURN DATE_ADD(p_from, INTERVAL fn_gen_random_int(0, TIMESTAMPDIFF(SECOND, p_from, p_to)) SECOND);
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_email`(p_given VARCHAR(60), p_family VARCHAR(60), p_seq BIGINT) RETURNS varchar(80) CHARSET utf8mb4
    NO SQL
BEGIN
    RETURN CONCAT(LEFT(fn_gen_slug(p_given), 20), '.', LEFT(fn_gen_slug(p_family), 20),
                  '.', p_seq, '@', fn_gen_email_domain());
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_email_domain`() RETURNS varchar(20) CHARSET utf8mb4
    NO SQL
BEGIN
    RETURN ELT(fn_gen_random_int(1, 3), 'example.com', 'example.org', 'example.net');
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_gender_id`() RETURNS tinyint unsigned
    NO SQL
BEGIN
    RETURN fn_gen_random_int(1, 2);
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_is_active`(p_index INT, p_total INT, p_active_pct DECIMAL(5,2)) RETURNS tinyint
    NO SQL
    DETERMINISTIC
BEGIN
    DECLARE v_active_total BIGINT;
    SET v_active_total = CAST(ROUND(p_total * p_active_pct / 100) AS SIGNED);
    RETURN IF((p_index * v_active_total) DIV p_total > ((p_index - 1) * v_active_total) DIV p_total, 1, 0);
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_nickname`(p_given VARCHAR(60), p_family VARCHAR(60), p_seq BIGINT) RETURNS varchar(100) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
    RETURN CONCAT(LEFT(fn_gen_slug(p_given), 1), LEFT(fn_gen_slug(p_family), 20), p_seq);
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_password_hash`() RETURNS varchar(255) CHARSET utf8mb4
    NO SQL
BEGIN
    RETURN SHA2(CONCAT(UUID(), RAND()), 256);
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_random_int`(p_min INT, p_max INT) RETURNS int
    NO SQL
BEGIN
    RETURN p_min + FLOOR(RAND() * (p_max - p_min + 1));
END ;;

CREATE DEFINER=`jose.amaro`@`%` FUNCTION `fn_gen_slug`(p_text VARCHAR(150)) RETURNS varchar(150) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
    RETURN LOWER(REPLACE(REPLACE(REPLACE(REPLACE(p_text, ' ', ''), '''', ''), '-', ''), '.', ''));
END ;;

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_pay_order`(
    IN p_order_id               INT UNSIGNED,
    IN p_user_payment_method_id BIGINT UNSIGNED,
    IN p_payment_method_name    VARCHAR(100),
    IN p_installments           TINYINT UNSIGNED
)
    MODIFIES SQL DATA
