    DECLARE v_order_user  INT DEFAULT NULL;
    DECLARE v_total       DECIMAL(10,2) DEFAULT NULL;
    DECLARE v_status      VARCHAR(20) DEFAULT NULL;
    DECLARE v_upm_user    INT DEFAULT NULL;
    DECLARE v_upm_status  BIT DEFAULT b'0';
    DECLARE v_upm_type    VARCHAR(30) DEFAULT NULL;
    DECLARE v_method_id   INT UNSIGNED DEFAULT NULL;
    DECLARE v_cuota       DECIMAL(10,2);
    DECLARE v_k           INT DEFAULT 1;
